    add_compat = mul_compat = True
    for a in states:
        for b in states:
            if not N.behavior_rel(a, b):
                continue
            for c in states:
                for d in states:
                    if not N.behavior_rel(c, d):
                        continue
                    if not N.behavior_rel(vor(a, c), vor(b, d)):
