function BEHAVIOR_CONGRUENCE(states, alphabet, step, observe, max_depth):
    words <- [empty_word]
    for length in 1..max_depth:
        words <- words ++ all sequences over alphabet of that length
    buckets <- empty map (signature -> list of states)
    for x in states:
        sig <- []
        for w in words:
            s <- x
            for a in w: s <- step(s, a)
            sig.append(observe(s))
        buckets[tuple(sig)].append(x)
    return values(buckets)            # the list of behavior classes

function MYHILL_NERODE_QUOTIENT(classes):
    reps <- [ cls[0] for cls in classes ]
    lookup <- empty map
    for i, cls in enumerate(classes):
        for x in cls: lookup[x] <- i
    function class_index(x): return lookup[x]
    return (reps, class_index)

function QUOT_OBS_DIST(class_index):
    return function d(x, y):
        return 0 if class_index(x) == class_index(y) else 1

function VERIFY_METRIC_AXIOMS(states, d):
    for x in states:
        assert d(x, x) == 0
        for y in states:
            assert d(x, y) >= 0 and d(x, y) == d(y, x)
            for z in states:
                assert d(x, z) <= d(x, y) + d(y, z)
    # separation holds by construction: d(x,y)=0 iff same class
    return true

